import {initTeacher,teacherSettings,teacherControls,teacherClick,teacherChange,requestReview} from './ai-teacher.js?v=writing-topic-8';
import {compareExpression,corePhrases,teacherPrompt} from './corrections.js?v=writing-topic-8';
import {COURSE_KEY,emptyCourse,loadCourse,essayDraft,checkEssay,retryEssay,gapMatches,paragraphParts,nextGroupIds,groupProgress,upgradeSentenceSession} from './course.js?v=writing-topic-8';
import {STORAGE_KEY,emptyState,loadState,start,submitExpression,resolveExpression,acceptTeacherReview,next,advanceItem,completeLesson,dueEntries,containsExpression,escapeHTML as esc} from './core.js?v=writing-topic-8';
const $=s=>document.querySelector(s);let data,state,byId,training,courseState,usageData,storageOK=true,speechToken=0,currentUtterance;let libraryMode='vocab';let libraryQuery='',librarySection='all',libraryLimit=50;
const titles={teacher:'AI 老师设置',home:'学习总览',vocabulary:'高频词汇',collocations:'场景搭配',practice:'正在练习',review:'错题与复习',library:'素材索引',notebook:'我的句子',about:'学习方法与资料说明',topic:'场景搭配',group:'板块学习',essays:'范文填空',essay:'范文填空'};
const active=()=>state.session&&state.session.phase!=='complete';const current=()=>byId.get(state.session?.ids[state.session.index]);
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{storageOK=false;$('#storage-warning').hidden=false;$('#storage-warning').textContent='当前浏览器无法保存进度。请在离开前导出“我的句子”。';}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function stopAudio(){speechToken++;if('speechSynthesis' in window)speechSynthesis.cancel();currentUtterance=null;}
function speak(text){if(!text)return;if(!('speechSynthesis' in window)){toast('当前浏览器不支持朗读，请使用支持英语语音的浏览器。');return;}stopAudio();const token=speechToken;const u=new SpeechSynthesisUtterance(text);u.lang=state.settings.accent;u.rate=state.settings.rate;u.volume=state.settings.volume;const voices=speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang===u.lang)||voices.find(v=>v.lang.startsWith('en'))||null;currentUtterance=u;u.onstart=()=>{if(token===speechToken&&$('#audio-status'))$('#audio-status').textContent='正在朗读…';};u.onend=()=>{if(token===speechToken&&$('#audio-status'))$('#audio-status').textContent='点击可重播 · Alt + P';};u.onerror=e=>{if(!['interrupted','canceled'].includes(e.error))toast('朗读暂不可用。请检查设备英语语音与音量，再点击播放。');};speechSynthesis.speak(u);}
const audio=(text,label='朗读')=>`<button type="button" class="audio-button" data-speak="${esc(text)}" aria-label="${esc(label)}">♪ <span>${label}</span></button>`;
const source=w=>`<p class="source">${w.id.startsWith('v-')?'高频词汇 · '+esc(w.section)+' · PDF 第 '+[...new Set(w.sources.map(s=>s.page))].join('、'):'分场景搭配 · '+esc(data.topics.find(t=>t.id===w.topic)?.title)+' · PDF 第 '+(w.sources?.length?[...new Set(w.sources.map(s=>s.page))].join('、'):w.page)} 页</p>`;
const meaning=w=>usageData?.[w.id]?.meaning||w.meaning;
const correctionRequests=new Map();
const header=(k,t,d)=>`<header class="page-heading"><div class="eyebrow">${k}</div><h1>${t}</h1><p>${d}</p></header>`;
function resume(){return active()?`<div class="resume"><div><b>还有一组练习等你继续</b><p>${state.session.kind==='vocab'?'高频词汇':'场景搭配'} · 第 ${state.session.index+1} / ${state.session.ids.length} 项，进度已保存。</p></div><a href="#practice" class="primary">继续练习 ↗</a><button data-action="end" class="quiet">结束本组</button></div>`:'';}
function audioSettings(kind=state.session?.kind){const goalKey=kind==='vocab'?'vocabRepairGoal':'repairGoal';return `<div class="audio-settings"><label>口音<select id="accent"><option value="en-GB" ${state.settings.accent==='en-GB'?'selected':''}>英式英语</option><option value="en-US" ${state.settings.accent==='en-US'?'selected':''}>美式英语</option></select></label><label>语速<select id="rate">${[[.65,'慢速'],[.85,'适中'],[1,'正常']].map(([v,t])=>`<option value="${v}" ${state.settings.rate===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="setting-wide" for="volume">播放音量 <output id="volume-value" for="volume">${Math.round(state.settings.volume*100)}%</output><input id="volume" type="range" min="0" max="100" step="1" value="${Math.round(state.settings.volume*100)}" aria-describedby="volume-help"></label><p id="volume-help" class="small setting-wide">0% 为静音；调整后从下一次播放生效。</p><label class="setting-wide">${kind==='vocab'?'词汇订正次数（默认五遍）':'场景表达订正次数'}<select id="${goalKey}">${Array.from({length:10},(_,i)=>i+1).map(n=>`<option value="${n}" ${state.settings[goalKey]===n?'selected':''}>${n} 遍</option>`).join('')}</select></label><p class="small setting-wide">两类练习分别保存次数；范文错空可单独重练。从下一次新错题开始生效，当前错题的目标次数保持不变。</p></div>`;}

function home(){const practised=Object.values(state.records).filter(r=>r.practised>0).length,completed=data.lessons.filter(l=>state.records[l.id]?.completed>0).length;
$('#main').innerHTML=`<section class="hero"><div><div class="eyebrow">ZHIHAN’S STUDY / IELTS WRITING</div><h1>不止记住单词。<br>把想法，<em>写出来。</em></h1><p class="lede">从一个准确的词，到一组自然的搭配。<br>理解、搭配、表达，让词汇走进你的下一篇作文。</p><div class="actions"><a class="primary" href="#vocabulary">开始词汇练习 <span>↗</span></a><a class="text-link" href="#collocations">探索场景搭配 →</a></div><div class="hero-stats"><span><b>${data.vocabulary.length}</b> 高频词练习</span><span><b>20</b> 写作话题</span><span><b>${training.expressions.length}</b> 场景表达</span></div></div><div class="writing-visual"><div class="paper-top"><span>A THOUGHT, WELL EXPRESSED</span><span>01 — 03</span></div><p class="draft-line">Education helps people.</p><p class="refined">Practical training helps<br>graduates <mark>develop expertise</mark><br>in their chosen field.</p><div class="margin-note">词汇 + 搭配 + 具体语境</div><div class="paper-bottom"><span>从“知道”，走向“会用”。</span><span class="pen">✎</span></div></div></section>${resume()}<section><div class="section-title"><div><div class="eyebrow">TWO WAYS TO PRACTISE</div><h2>从主题词组，走到完整文章。</h2></div><span>你的独立写作学习室</span></div><div class="path-grid"><a href="#vocabulary" class="path-card"><span class="path-number">01 / WORDS</span><h3>看懂意思，准确表达。</h3><p>按话题学习用法 → 看中文写英文 → 核对表达。<br>答错加入错题本，按设定次数正确重写（当前 <b>${state.settings.vocabRepairGoal} 遍</b>）。</p><span class="text-link">高频词汇 ↗</span></a><a href="#collocations" class="path-card"><span class="path-number">02 / EXPRESSIONS</span><h3>理解，然后用起来。</h3><p>按相关论点分组 → 记忆与回忆全部表达。<br>学完可进入范文填空，也可直接结束。</p><span class="text-link">场景搭配 ↗</span></a></div></section><section class="progress-strip"><div><strong>${practised}</strong><span>已练习表达</span></div><div><strong>${training.essays.filter(e=>courseState.essays[e.id]?.completed).length} / ${training.essays.length}</strong><span>范文填空曾全部匹配</span></div><div><strong>${dueEntries(state,[...data.vocabulary,...data.lessons]).length}</strong><span>到期复习</span></div><a href="#review">把记忆再唤醒一次 →</a></section>`;}
function vocabulary(){groupIndex();}
function collocations(){const gs=training.groups.filter(g=>g.kind==='collocation');$('#main').innerHTML=header('CONNECTED EXPRESSIONS','相关的表达，放在一起记。',`20 个话题 · ${training.meta.groups} 个关联小组。同一论点的搭配合成整句：${training.meta.sentences} 个整句学习项，与独立短语一起覆盖全部 1,537 条来源表达。`)+resume()+`<div class="method-banner"><span>01 成组理解</span><i>→</i><span>02 逐项回忆</span><i>→</i><span>03 可选范文</span><i>→</i><span>04 拆解思路</span></div><div class="topic-grid">${data.topics.map((t,i)=>{const groups=gs.filter(g=>g.topic===t.id),ids=groups.flatMap(g=>g.entryIds);return `<a class="topic-card" href="#topic/${t.id}"><span class="path-number">${String(i+1).padStart(2,'0')} / TOPIC</span><h2>${esc(t.title)}</h2><p>${groups.slice(0,2).map(g=>esc(g.title)).join(' · ')}</p><div><span>${groups.length} 组 · ${ids.length} 项 · ${ids.filter(id=>state.records[id]?.practised).length} 已练</span><b>↗</b></div></a>`}).join('')}</div>`;}

function topic(id){const t=data.topics.find(t=>t.id===id);if(!t){location.hash='collocations';return;}const groups=training.groups.filter(g=>g.kind==='collocation'&&g.topic===id);$('#main').innerHTML=header('TOPIC / '+id.slice(-2),esc(t.title),'按教材话题看全貌：先选写作角度，再成组掌握相关词组和整句。完成后可用范文练习组织论证。')+resume()+`<div class="actions"><a class="text-link" href="#collocations">← 全部话题</a><a class="secondary" href="#essay/${groups[0].essayId}">本话题范文填空 ↗</a></div>${topicRoadmap(t,groups)}${groupCards(groups)}<section class="source-bank"><h2>原资料 · 语境核对</h2><p class="small">中文提示有时来自完整论点，不等于逐词翻译。原文的群体概括与因果判断不作为已核实事实；练习表达时仍须根据具体题目限定范围。</p><details><summary>查看 ${t.ideas.length} 条原文语境与页码</summary><div class="source-ideas">${t.ideas.map(b=>`<article><p>${esc(b.text)}</p><small>PDF 第 ${b.page} 页</small></article>`).join('')}</div></details></section>`;}

function pronunciationPrompt(){const s=state.session,w=current();if(!s||!w)return;if(s.kind==='vocab'||s.flow==='block')speak(w.word);else if(['study','recall-ok','gap-ok','mistake','selfcheck'].includes(s.phase))speak(w.word);else toast('先回忆表达；答案揭晓后可以听发音。');}
function answerForm(label,placeholder='写下你的英文答案…'){const sentence=current()?.unitType==='sentence';return `<form id="answer-form" autocomplete="off"><label class="input-label" for="answer">${sentence?'写出完整英文句子':label}</label>${sentence?`<textarea id="answer" name="answer" rows="4" maxlength="500" spellcheck="false" autocapitalize="none" autocorrect="off" autocomplete="off" placeholder="写下完整句子，包含主语、连接词与全部要点…" aria-describedby="answer-error sentence-input-help"></textarea><p id="sentence-input-help" class="small">Enter 检查答案 · Shift + Enter 换行。重点表达完整原意，使用正确的语法与搭配；不必逐词复现参考。</p>`:`<input id="answer" name="answer" type="text" maxlength="500" spellcheck="false" autocapitalize="none" autocorrect="off" autocomplete="off" placeholder="${placeholder}" aria-describedby="answer-error">`}<p id="answer-error" role="status" class="error"></p><button type="submit" class="primary">检查答案 <kbd>Enter ↵</kbd></button></form>`;}

function answerReveal(w){return `<div class="answer-reveal ${w.unitType==='sentence'?'sentence-reveal':''}">${w.unitType==='sentence'?'<p class="eyebrow">完整句子 · 一起记忆</p>':''}<h2 lang="en">${esc(w.word)}</h2><p>${esc(meaning(w))}</p>${audio(w.word,'播放发音')}${w.note?`<p class="tip">整理说明：${esc(w.note)}</p>`:''}${usagePanel(w)}${source(w)}</div>`;}
function practice(){correctionRequests.clear();const s=state.session;if(!s){$('#main').innerHTML=header('READY WHEN YOU ARE','从一组练习开始。','先选择高频词汇或场景搭配。')+'<div class="actions"><a class="primary" href="#vocabulary">高频词汇</a><a class="secondary" href="#collocations">场景搭配</a></div>';return;}const w=current();let body='';
if(s.phase==='block-study')body=blockStudy(s);
else if(s.phase==='complete'&&s.flow==='block')body=blockComplete(s);
else if(s.phase==='complete')body=`<div class="complete-symbol">✦</div><h1>这一组，练完了。</h1><p>完成 ${s.ids.length} 项练习。错题与复习时间已保存，造句可在“我的句子”回看。</p><div class="actions"><a class="primary" href="#${s.kind==='vocab'?'vocabulary':'collocations'}">再选一组 ↗</a><a class="secondary" href="#review">查看复习计划</a></div>`;
else if(s.phase==='question')body=translationQuestion(s);
else if(s.phase==='study')body=`<div class="eyebrow">01 / NOTICE THE EXPRESSION</div><h1>先读懂它的用法。</h1>${answerReveal(w)}<blockquote lang="en">${esc(w.example)}</blockquote><p class="tip">${esc(w.tip)}</p><button class="primary" data-action="next">我记住了，隐藏答案 <kbd>Enter ↵</kbd></button>`;
else if(s.phase==='recall')body=`<div class="eyebrow">02 / RETRIEVE FROM MEMORY</div><h1>这个意思，你会怎么表达？</h1><p class="meaning-prompt">${esc(meaning(w))}</p><p class="small">回忆刚刚学过的搭配。本题练习目标表达，不评判其他合理译法。</p>${answerForm('写出刚刚学习的英文搭配')}`;
else if(s.phase==='gap')body=`<div class="eyebrow">03 / PUT IT IN CONTEXT</div><h1>让搭配回到句子里。</h1><blockquote lang="en">${esc(w.example).replace(esc(w.word),'<span class="gap">__________</span>')}</blockquote><p class="small">提示：${esc(meaning(w))}。按例句需要填入本次学过的表达。</p>${answerForm('补全句子中的完整搭配')}`;
else if(s.phase==='needs-review')body=`<div class="feedback">已保存你的表达 · 待核对</div><p>写法不同不代表有错，本次尚未计入错题。正确标准：语法正确、表达通顺、核心要点完整，重点短语保留且用法正确。不要求复现参考句。</p>${correctionPanel(w,s.lastAnswer)}<div class="actions"><button class="primary" data-expression-decision="valid">核对后：我的表达成立</button><button class="secondary" data-expression-decision="error">核对后：有错误，加入订正练习</button><button class="quiet" data-expression-decision="skip">暂不判断，跳过本项</button></div><p class="small">AI 四项核对通过会自动记为正确；也可自行按以上标准确认。确认有误才记录错题并按设定次数巩固。</p>`;
else if(s.phase==='mistake')body=`<div class="feedback error-tag">订正与巩固 · 已记录到错题本</div>${correctionPanel(w,s.lastAnswer)}${answerReveal(w)}<p>先核对表达与搭配，再隐藏答案。本次需正确改写 <b>${s.repairGoal} 遍</b>，已完成 ${s.repeats} 遍。</p><button class="primary" data-action="next">隐藏答案，重新表达 <kbd>Enter ↵</kbd></button>`;
else if(s.phase==='repair')body=`<div class="eyebrow">RECALL AGAIN / 已完成 ${s.repeats} / ${s.repairGoal} 遍</div><h1>根据中文，再正确表达一遍。</h1><p class="meaning-prompt">${esc(meaning(w))}</p>${s.kind==='vocab'||s.flow==='block'?audio(w.word,'重播读音'):''}<details class="usage-hint"><summary>查看用法与搭配（会显示英文）</summary>${usagePanel(w)}</details>${answerForm(`第 ${s.repeats+1} / ${s.repairGoal} 遍 · 只计入正确答案`)}`;
else if(['correct','repaired','recall-ok','gap-ok'].includes(s.phase))body=`<div class="feedback">✓ ${s.phase==='repaired'?`重写正确 · 已完成 ${s.repairGoal} 遍`:s.aiSummary?'AI 核对通过：表达正确':s.acceptedAlternative?'已核对：表达成立':s.phase==='gap-ok'?'语境目标已匹配':s.kind==='vocab'?'拼写正确':'已匹配收录表达'} · 查看用法与搭配</div>${s.aiSummary?`<div class="callout"><p>${esc(s.aiSummary)}</p><p lang="en">${esc(s.lastAnswer)}</p><p class="small">语法、通顺度、核心要点与重点短语四项核对通过，无需照抄参考。</p></div>`:''}${s.phase==='repaired'&&state.records[w.id]?.lastAnswer?`<details class="past-correction"><summary>回看刚才的表达与订正</summary>${correctionPanel(w,state.records[w.id].lastAnswer)}</details>`:''}${answerReveal(w)}<button class="primary" data-action="next">${s.phase==='recall-ok'?'放进句子练一练':s.phase==='gap-ok'?'试着自己造句':s.index+1===s.ids.length?'查看本组结果':'下一项'} <kbd>Enter ↵</kbd></button>`;
else if(['write','selfcheck'].includes(s.phase)){const has=containsExpression(s.draft,w.word);body=`<div class="eyebrow">04 / MAKE IT YOURS</div><h1>写一个属于你的句子。</h1><p class="meaning-prompt">${esc(w.prompt)}</p><p class="small">尝试使用 <strong lang="en">${esc(w.word)}</strong>。可以根据语境调整时态、代词与单复数。</p><label class="input-label" for="sentence">你的英文句子或短段落</label><textarea id="sentence" maxlength="10000" placeholder="写一个具体的观点、原因或例子…">${esc(s.draft)}</textarea><p class="small">自动保存在当前浏览器。Enter 换行；本步骤用按钮继续。</p>${s.phase==='write'?`<div class="actions"><button class="primary" data-action="selfcheck">保存并打开自查 →</button><button class="quiet" data-action="skip-writing">稍后再写</button></div>`:`<div class="selfcheck"><p class="feedback">已保存草稿 · 等待你自查</p><p>${has?'已找到本次搭配的完整形式。':'未找到搭配的完整原形；如果你改了时态或代词，请自行核对。'}</p><p class="small">这里只检查表达是否出现，不自动判断语法、论证质量，也不提供雅思分数。</p><details><summary>对照参考例句与用法</summary><blockquote lang="en">${esc(w.example)}</blockquote><p>${esc(w.tip)}</p></details>${['搭配与介词用对了，并核对了词形变化。','检查了主谓一致、冠词和句子结构。','句子回应了问题，有具体含义，避免无依据的绝对化结论。'].map((t,i)=>`<label class="checkbox"><input type="checkbox" data-check="${i}" ${s.checks.includes(i)?'checked':''}>${t}</label>`).join('')}<button class="primary" data-action="finish-lesson">我已自查，完成这一项 →</button></div>`}`;}
$('#main').innerHTML=`<div class="practice-top"><a href="#${s.kind==='vocab'?'vocabulary':'collocations'}">← ${s.kind==='vocab'?'高频词汇':'场景搭配'}</a><span>${s.phase==='complete'?s.ids.length:s.index+1} / ${s.ids.length}</span><button class="quiet" data-action="end">结束本组</button></div><div class="progress-track"><i style="width:${100*(s.phase==='complete'?1:s.index/s.ids.length)}%"></i></div><div class="practice-layout"><section class="exercise ${w?.unitType==='sentence'?'sentence-exercise':''}" aria-live="polite">${body}</section><aside class="practice-aside">${audioSettings()}<h3>${s.flow==='block'?'表达练习提示':s.kind==='vocab'?'翻译小提示':'搭配学习小提示'}</h3><p>${s.kind==='vocab'||s.flow==='block'?'先看中文表达意思，再核对结构和搭配。发音按需点击；词汇答对自动朗读；答错后看用法，再按设定次数改写。':'先回忆，再放进语境，最后用自己的观点造句。词形变化留给造句阶段练习。'}</p><p class="small">${s.kind==='vocab'?'本模块训练教材目标词的拼写，接受已收录答案及英美拼写变体；未匹配进入错题订正。':'句子不要求逐词一致；改写先核对语法、搭配与核心要点，未核对不判为正确。'}</p><a href="#review" class="text-link">错题与复习 →</a></aside></div>`;$('#answer')?.focus({preventScroll:true});if(s.groupId&&$('#main .practice-top>a'))$('#main .practice-top>a').href='#group/'+s.groupId;}
function review(){correctionRequests.clear();const entries=[...data.vocabulary,...data.allLessons],due=dueEntries(state,entries),mistakes=entries.filter(e=>state.records[e.id]?.errors>0);$('#main').innerHTML=header('RETURN TO WHAT MATTERS','隔一段时间，再想起来。','按设定次数重写是当下巩固；隔天再回忆，才能检验是否真正记住。')+resume()+`<div class="review-grid">${[['vocab','高频词汇',data.vocabulary],['collocation','场景搭配',data.lessons]].map(([kind,title,list])=>{const d=due.filter(e=>list.includes(e)),m=list.filter(e=>state.records[e.id]?.errors>0&&!state.records[e.id].resolved);return `<section class="panel"><div class="eyebrow">${kind==='vocab'?'WORDS':'EXPRESSIONS'}</div><h2>${title}</h2><p><b>${d.length}</b> 项到期复习 · <b>${m.length}</b> 项待巩固</p><div class="actions"><button class="primary" data-review="${kind}:due" ${d.length?'':'disabled'}>练到期项</button><button class="secondary" data-review="${kind}:wrong" ${m.length?'':'disabled'}>练待巩固项</button></div></section>`;}).join('')}</div><section class="panel"><h2>复习计划</h2><p>首次答对或完成自查后，约 24 小时后再练；连续顺利完成后，间隔依次延长为 3、7、14 天。出错后回到 1 天。造句完成记录表示你已自查，并非系统评定掌握。</p><p class="small">进度只保存在当前浏览器；网站不会后台发送通知。回来打开本页即可看到到期项目。</p></section><div class="section-title"><h2>错题记录</h2><p class="small">旧版记录可能仅因未匹配参考而产生，不代表已确认语法错误。旧短语记录继续保留；已合并的条目点击再练会进入对应整句，整句成绩单独记录。</p><span>${mistakes.length} 项，巩固后仍保留</span></div><div class="word-list">${mistakes.length?mistakes.map(e=>{const r=state.records[e.id];return `<article class="word-row"><div><h3 lang="en">${esc(e.word)}</h3><p>${esc(meaning(e))}</p><small>${r.resolved?'已巩固':'待巩固'} · 首次检查错 ${r.errors} 次 · 下次复习 ${r.due?new Date(r.due).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}):'尚未安排'}</small>${r.lastAnswer?`<details class="past-correction"><summary>查看我的表达与订正</summary>${correctionPanel(e,r.lastAnswer)}</details>`:''}</div><button class="secondary" data-single="${e.id}">再练一次</button></article>`;}).join(''):'<p class="empty">还没有错题。先开始一组练习。</p>'}</div>`;}
function library(){const sections=[...new Set(data.vocabulary.map(v=>v.section))];$('#main').innerHTML=header('A PERSONAL REFERENCE','把表达，放在手边。','检索词汇、释义与场景搭配。每条保留来源页码；原资料的扩展素材可在各话题页浏览。')+`<div class="filter-bar"><label><span class="sr-only">搜索表达或中文</span><input id="library-search" type="search" placeholder="搜索英文、中文或用法…" value="${esc(libraryQuery)}"></label><label><span class="sr-only">资料类型</span><select id="library-mode"><option value="vocab" ${libraryMode==='vocab'?'selected':''}>高频词汇</option><option value="collocation" ${libraryMode==='collocation'?'selected':''}>场景搭配</option></select></label><label><span class="sr-only">词汇场景</span><select id="library-section" ${libraryMode==='vocab'?'':'disabled'}><option value="all">全部场景</option>${sections.map(s=>`<option value="${esc(s)}" ${librarySection===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label></div><p id="library-count" class="small" role="status"></p><div id="library-results"></div>`;libraryResults();}
function libraryResults(){const q=libraryQuery.toLowerCase();const list=(libraryMode==='vocab'?data.vocabulary:data.lessons).filter(e=>(libraryMode!=='vocab'||librarySection==='all'||e.section===librarySection)&&[e.word,meaning(e),e.meaning,e.tip,e.note].join(' ').toLowerCase().includes(q));$('#library-count').textContent=`找到 ${list.length} 项 · 已显示 ${Math.min(list.length,libraryLimit)} 项`;$('#library-results').innerHTML=`<div class="word-list">${list.slice(0,libraryLimit).map(e=>`<article class="word-row"><div><h3 lang="en">${esc(e.word)}</h3><p>${esc(meaning(e))}</p>${e.note?`<p class="tip">${esc(e.note)}</p>`:''}${e.tip?`<p class="small">${esc(e.tip)}</p>`:''}${usagePanel(e,true)}${source(e)}${e.sources&&e.note?`<details><summary>查看原条目</summary>${e.sources.map(s=>`<p>${esc(s.word??s.phrase)} · ${esc(s.meaning??s.cue)} · PDF ${s.page}</p>`).join('')}</details>`:''}</div><div class="row-actions">${audio(e.word)}<button class="quiet" data-single="${e.id}">练习 →</button></div></article>`).join('')}</div>${list.length>libraryLimit?'<button class="secondary wide" data-action="more-library">继续显示 50 项 ↓</button>':''}${!list.length?'<p class="empty">没有找到匹配项，试试更短的关键词。</p>':''}`;}
function notebook(){const notes=data.allLessons.filter(l=>state.notes[l.id]);$('#main').innerHTML=header('YOUR SENTENCES','让表达留下你的痕迹。','保存的句子是你的写作草稿。回看、修改、核对，再把它们用于新的话题。')+`<div class="actions"><button class="primary" data-action="export">导出句子与练习记录 ↓</button><a class="text-link" href="#collocations">再学一个搭配 →</a></div><p class="small">${notes.length} 份草稿，保存在当前浏览器。导出为 Markdown，可自行备份。</p><div class="note-list">${notes.map(l=>`<article class="note-card"><div class="eyebrow">${data.topics.find(t=>t.id===l.topic).title} · ${state.records[l.id]?.completed?'曾完成自查':'草稿'}</div><h2 lang="en">${esc(l.word)}</h2><label class="sr-only" for="note-${l.id}">编辑 ${esc(l.word)} 的句子</label><textarea id="note-${l.id}" data-note="${l.id}" maxlength="10000">${esc(state.notes[l.id])}</textarea><p class="small">修改自动保存；修改后请重新核对语法和论证。</p><details><summary>参考用法</summary><p lang="en">${esc(l.example)}</p><p>${esc(l.tip)}</p></details></article>`).join('')||'<p class="empty">还没有写下句子。完成一个搭配的回忆与填空后，试着表达自己的观点。</p>'}</div>`;}
function about(){$('#main').innerHTML=header('HOW THIS ROOM WORKS','按主题记忆，把表达连成文章。','词汇、搭配和范文是同一条学习路线；范文是可选环节。')+`<section class="prose panel"><h2>新的学习路线</h2><p>高频词汇分为 28 个板块；场景搭配覆盖 20 个话题、${training.meta.groups} 个关联小组。同一原文论点中的搭配合成完整英文句子，共 ${training.meta.sentences} 个整句学习项；与独立短语一起覆盖 1,537 条来源表达。分组按原文相邻论点与页内主题组织；词汇块中包含词、短语以及可用于句子的表达。</p><p>先学习意思、结构与搭配，再根据中文写英文。发音按钮按需播放，不自动朗读；与参考不同的写法先核对语法、搭配和原意，确认有误后才记入错题并按设定次数巩固，默认 1 遍。每个新小组优先选未练项，完成后可继续当前板块，也可以直接结束。</p><h2>可选的范文填空</h2><p>27 篇原创 Task 2 教学范文覆盖两类资料的全部主题；相关板块共享一篇对应文章。每篇 270–303 词，自拟题目，选用部分相关表达形成自然论证，不强行串入全部词。先给中文提示，整篇填写后再展示参考表达、完整文章和四段论证思路。</p><p>填空按目标表达及列明的可接受形式检查，允许常见英美拼写与标点差异；其他合理改写可能未匹配，需要自行结合语法和上下文核对。匹配数量不是雅思分数。原文素材中的群体概括、因果论断也不是经本站验证的事实。</p><p><a href="https://ielts.org/take-a-test/test-types/ielts-academic-test/ielts-academic-format-writing" target="_blank" rel="noopener">IELTS 官方要求</a>：Task 2 至少 250 词，评分包括回应任务、连贯衔接、词汇及语法。本站范文用于分析语言与论证，不是官方范文或分数保证。</p><h2>来源、订正与旧记录</h2><p>来源为用户提供的新东方在线雅思研发中心《雅思写作话题高频词汇》《雅思写作话题分场景搭配》。高频词汇 887 条原记录整理为 903 项练习。搭配保留 1,537 条表达的原始语境和页码，订正明显拼写、搭配及不完整表达。部分中文是语境提示而非精确逐词翻译，可展开核对原文。</p><p>旧条目的成绩和句子草稿继续保留；含有已合并短语的未完成练习会回到整句预习，整句成绩单独记录；新练习不要求每个表达都造句。此前的造句记录仍在“我的句子”中，可继续编辑和导出。</p><h2>保存与复习</h2><p>音量、错题次数、学习进度与范文草稿只保存在当前浏览器，没有账号同步。清除网站数据会删除本地记录，请定期导出。听力和计量站的记录不受影响。发音使用设备英语语音；间隔复习是练习安排，不是效果保证。</p></section>`;}
function render(){stopAudio();const [rawRoute,id]=location.hash.slice(1).split('/');const route=rawRoute||'home';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+(route==='topic'?'collocations':route==='group'?(training.groups.find(g=>g.id===id)?.kind==='vocab'?'vocabulary':'collocations'):route==='essay'?'essays':route)));$('#breadcrumb').textContent=titles[route]||titles.home;$('#due-label').textContent=`到期复习 · ${dueEntries(state,[...data.vocabulary,...data.lessons]).length}`;$('#sidebar').classList.remove('open');$('#scrim').hidden=true;$('#menu').setAttribute('aria-expanded','false');({home,vocabulary,collocations,practice,review,library,notebook,about,teacher:()=>{$('#main').innerHTML=teacherSettings();},topic:()=>topic(id),group:()=>groupPage(id),essays:essayIndex,essay:()=>essayPage(id)}[route]||home)();if(route==='review')$('#main').insertAdjacentHTML('beforeend',essayReview());}
function begin(kind,ids,groupId=''){ids=[...new Set(ids.map(id=>training.replacements?.[id]||id))];if(active()){toast('当前组尚未结束。请先继续，或点击“结束本组”再开始新的一组。');return;}if(!start(state,kind,ids,{flow:'block',groupId})){toast('这个范围内没有练习。');return;}save();if(location.hash==='#practice')practice();else location.hash='practice';}
function finishStep(){if(next(state)){save();practice();}}
function exportNotes(){const lines=['# Zhihan · 雅思写作学习记录','',`导出时间：${new Date().toLocaleString('zh-CN')}`,''];for(const l of data.allLessons)if(state.notes[l.id])lines.push(`## ${l.word}`,l.meaning,'',state.notes[l.id],'',`自查完成次数：${state.records[l.id]?.completed||0}`,'');lines.push('## 练习记录','');for(const [id,r] of Object.entries(state.records)){const e=byId.get(id);if(e&&r.lastAnswer)lines.push('你的最近一次未匹配表达：'+r.lastAnswer);if(e)lines.push(`- ${e.word}：检查 ${r.attempts} 次，正确 ${r.correct} 次，错误 ${r.errors} 次；${r.resolved?'已巩固':'待巩固'}；下次复习 ${r.due?new Date(r.due).toLocaleString('zh-CN'):'未安排'}`);}lines.push('## 范文填空记录','');for(const e of training.essays){const d=courseState.essays[e.id];if(d){lines.push('### '+e.title,e.prompt,'');for(const g of e.gaps)lines.push('- '+g.hint+'：'+(d.answers[g.id]||'未填写'));lines.push('检查次数：'+d.attempts+'；曾全部匹配：'+(d.completed?'是':'否'),'');}}const url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Zhihan-writing-notes.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function init(){try{const res=await fetch('data/content.json');if(!res.ok)throw Error();data=await res.json();const tr=await fetch('data/course.json?v=writing-topic-8');if(!tr.ok)throw Error('课程未能加载');training=await tr.json();const ur=await fetch('data/usage.json?v=writing-topic-8');if(!ur.ok)throw Error('用法未能加载');usageData=(await ur.json()).entries;await initTeacher();data.legacyLessons=data.lessons;data.lessons=training.expressions;const all=new Map([...(training.legacyExpressions||[]),...data.legacyLessons,...data.lessons].map(e=>[e.id,e]));for(const l of data.legacyLessons){const current=all.get(l.id);if(current&&!current.unitType)all.set(l.id,{...current,example:l.example,tip:l.tip,prompt:l.prompt});}data.allLessons=[...all.values()];byId=new Map([...data.vocabulary,...data.allLessons].map(e=>[e.id,e]));try{courseState=loadCourse(localStorage.getItem(COURSE_KEY),training.essays);}catch{courseState=emptyCourse();}try{state=loadState(localStorage.getItem(STORAGE_KEY),[...byId.values()]);}catch{state=emptyState();storageOK=false;}const upgraded=upgradeSentenceSession(state,training.replacements||{});save();render();if(upgraded)toast('本组已更新为整句学习。请先预习完整句子；原有短语记录已保留。');}catch{$('#main').innerHTML='<h1>资料暂时未能加载</h1><p>请检查网络后刷新。</p><button class="primary" onclick="location.reload()">重新加载</button>';return;}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});window.addEventListener('pagehide',save);
$('#menu').onclick=()=>{const on=$('#sidebar').classList.toggle('open');$('#scrim').hidden=!on;$('#menu').setAttribute('aria-expanded',String(on));};$('#scrim').onclick=()=>{$('#sidebar').classList.remove('open');$('#scrim').hidden=true;$('#menu').setAttribute('aria-expanded','false');};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(teacherClick(b,render))return;if(handleCorrectionClick(b))return;if(handleCourseClick(b))return;if(b.dataset.expressionDecision){const result=resolveExpression(state,current(),b.dataset.expressionDecision);save();practice();if(result==='repair-progress')toast('已核对本次改写，继续完成剩余次数。');return;}if(b.dataset.speak){speak(b.dataset.speak);return;}if(b.dataset.topicStart){begin('collocation',data.topics.find(t=>t.id===b.dataset.topicStart).lessons);return;}const id=b.dataset.lesson||b.dataset.single;if(id){begin(id.startsWith('v-')?'vocab':'collocation',[id]);return;}if(b.dataset.review){const [kind,mode]=b.dataset.review.split(':');const list=kind==='vocab'?data.vocabulary:data.lessons;begin(kind,(mode==='due'?dueEntries(state,list):list.filter(e=>state.records[e.id]?.errors>0&&!state.records[e.id].resolved)).map(e=>e.id));return;}
switch(b.dataset.action){case 'start-vocab':{let list=data.vocabulary.filter(w=>state.settings.section==='all'||w.section===state.settings.section);if(state.settings.shuffle){list=[...list];for(let i=list.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[list[i],list[j]]=[list[j],list[i]];}}begin('vocab',list.slice(0,state.settings.size||list.length).map(w=>w.id));break;}case 'next':finishStep();break;case 'play':pronunciationPrompt();break;case 'end':{const gid=state.session?.groupId;state.session=null;save();if(gid)location.hash='group/'+gid;else render();}toast('本组已结束，历史记录和句子已保留。');break;case 'more-library':libraryLimit+=50;libraryResults();break;case 'export':exportNotes();break;case 'selfcheck':if(!state.session.draft.trim()){toast('先写下一句英文，再打开自查。');return;}state.notes[current().id]=state.session.draft;state.session.phase='selfcheck';save();practice();break;case 'finish-lesson':if(completeLesson(state,current())){save();practice();}else toast('请写下句子，并完成三个自查项后继续。');break;case 'skip-writing':if(state.session.draft.trim())state.notes[current().id]=state.session.draft;advanceItem(state);save();practice();break;}});
document.addEventListener('submit',e=>{if(e.target.id==='essay-form'){e.preventDefault();submitEssayPage();return;}if(e.target.id!=='answer-form')return;e.preventDefault();const value=$('#answer').value;if(!value.trim()){$('#answer-error').textContent='先写下答案，再检查。';return;}const w=current(),result=submitExpression(state,w,value);save();practice();if(state.session?.kind==='vocab'&&['correct','repaired','repair-progress'].includes(result))speak(w.word);if(result==='repair-progress')toast('本次改写正确，继续完成剩余次数。');});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.essayGap){const essay=training.essays.find(x=>x.id===el.dataset.essayId),d=essayDraft(courseState,essay);d.answers[el.dataset.essayGap]=el.value;d.submitted=false;saveCourse();return;}if(el.id==='volume'){state.settings.volume=Number(el.value)/100;$('#volume-value').textContent=el.value+'%';save();return;}if(el.id==='sentence'){state.session.draft=el.value;state.session.checks=[];state.notes[current().id]=el.value;save();if(state.session.phase==='selfcheck'){state.session.phase='write';save();/* Keep the caret while resetting stale self-check results. */const start=el.selectionStart,end=el.selectionEnd;practice();$('#sentence').focus();$('#sentence').setSelectionRange(start,end);}return;}if(el.dataset.note){state.notes[el.dataset.note]=el.value;save();return;}if(el.id==='library-search'){libraryQuery=el.value;libraryLimit=50;libraryResults();}});
document.addEventListener('change',e=>{const el=e.target;if(teacherChange(el,render))return;if(['accent','rate','size','section','shuffle','repairGoal','vocabRepairGoal'].includes(el.id)){state.settings[el.id]=el.id==='shuffle'?el.checked:['rate','size','repairGoal','vocabRepairGoal'].includes(el.id)?Number(el.value):el.value;save();}if(el.dataset.check!==undefined){const n=Number(el.dataset.check);state.session.checks=state.session.checks.filter(i=>i!==n);if(el.checked)state.session.checks.push(n);save();}if(el.id==='library-mode'){libraryMode=el.value;libraryLimit=50;library();}if(el.id==='library-section'){librarySection=el.value;libraryLimit=50;libraryResults();}});
document.addEventListener('keydown',e=>{if(e.isComposing||e.repeat)return;if(e.altKey&&e.key.toLowerCase()==='p'&&location.hash==='#practice'){e.preventDefault();pronunciationPrompt();return;}if(e.key==='Escape'){$('#scrim').click();return;}if(e.key==='Enter'&&e.target.id==='answer'&&e.target.tagName==='TEXTAREA'&&!e.shiftKey){e.preventDefault();$('#answer-form').requestSubmit();return;}if(e.key!=='Enter'||location.hash!=='#practice'||e.target.closest('input,textarea,select,button,a,summary'))return;if(['block-study','study','mistake','correct','repaired','recall-ok','gap-ok'].includes(state.session?.phase)){e.preventDefault();finishStep();}});
}
init();

function saveCourse(){try{localStorage.setItem(COURSE_KEY,JSON.stringify(courseState));}catch{toast('本次范文记录未能保存，请导出学习记录备份。');}}
function groupCards(groups){return `<div class="course-groups">${groups.map(g=>{const done=groupProgress(g,state);return `<a class="course-group panel" href="#group/${g.id}"><span class="eyebrow">${g.kind==='vocab'?'WORD BLOCK':'EXPRESSION CLUSTER'}</span><h3>${esc(g.title)}</h3><p>${g.entryIds.slice(0,3).map(id=>esc(byId.get(id).word)).join(' · ')}</p><div class="group-meta"><span>${g.entryIds.length} 个表达</span><span>${done} / ${g.entryIds.length} 已练 →</span></div><div class="progress-track"><i style="width:${done/g.entryIds.length*100}%"></i></div></a>`}).join('')}</div>`;}
function groupIndex(){$('#main').innerHTML=header('TOPIC-BASED WORD BANK','按话题，积累可以一起用的词。','28 个词汇板块。看中文写教材目标词，答对自动朗读并展示释义；答错默认正确重写五遍。学完可选范文填空或结束。')+resume()+[...new Set(training.groups.filter(g=>g.kind==='vocab').map(g=>g.topic))].map(topic=>`<section><div class="section-title"><h2>${esc(topic)}</h2></div>${groupCards(training.groups.filter(g=>g.kind==='vocab'&&g.topic===topic))}</section>`).join('');}
function promptSettings(){return `<div class="translation-method"><strong>中译英 · 把意思表达出来</strong><p>先学习中文意思、英文表达和搭配结构，再看中文写英文。发音按钮可随时按需使用。</p></div>`;}

function groupPage(id){const g=training.groups.find(g=>g.id===id);if(!g){location.hash='vocabulary';return;}const done=groupProgress(g,state);$('#main').innerHTML=header(g.kind==='vocab'?'VOCABULARY BLOCK':'COLLOCATION CLUSTER',esc(g.title),g.description)+resume()+`<div class="actions"><a class="text-link" href="#${g.kind==='vocab'?'vocabulary':'topic/'+g.topic}">← 返回板块目录</a><button class="secondary" data-open-essay="${g.essayId}" data-return-group="${g.id}">查看关联范文练习 ↗</button></div><div class="setup-grid"><section class="panel"><span class="eyebrow">${done} / ${g.entryIds.length} 已练</span><h2>${done===g.entryIds.length?'再巩固一次':'从未练的表达继续'}</h2><div class="field"><label for="size">本次小组数量</label><select id="size">${[5,10,20,0].map(n=>`<option value="${n}" ${n===state.settings.size?'selected':''}>${n?n+' 项':'本板块全部未练项'}</option>`).join('')}</select></div>${promptSettings()}<label class="checkbox"><input type="checkbox" id="shuffle" ${state.settings.shuffle?'checked':''}>在本板块内打乱本次顺序</label>${audioSettings(g.kind)}<button class="primary wide" data-start-group="${g.id}">开始成组学习 →</button><p class="small">优先选择未练项，不会每次都从前几个词开始。全部练完后可整组重练；“已练”表示完成回忆或纠错，不等于系统评定掌握。</p></section><aside class="method-panel"><div class="eyebrow">WORDS → ARGUMENT</div><h2>先理解用法，再练习表达。</h2><ol class="steps"><li><b>一起看</b><span>观察表达之间的主题联系，理解搭配结构；发音按需播放。</span></li><li><b>逐项写</b><span>隐藏英文，根据中文写出表达；核对搭配，错后按设定次数改写。</span></li><li><b>选择怎样结束</b><span>继续本板块、直接结束，或做关联话题的范文填空。</span></li><li><b>从词到论证</b><span>先看中文提示填空，提交后核对完整范文与段落思路。</span></li></ol><p class="small">范文自然选用相关板块的一部分表达；相关板块可能共享同一篇文章，不要求把全部词汇硬塞进作文。</p></aside></div>${g.kind==='collocation'?groupArgument(g):''}<details class="panel group-preview"><summary>预览本板块全部 ${g.entryIds.length} 个表达</summary>${studyCards(g.entryIds)}</details>`;}
function studyCards(ids){return `<div class="study-cards">${ids.map((id,i)=>{const w=byId.get(id);return `<article class="study-card ${w.unitType==='sentence'?'sentence-card':''}"><small>${String(i+1).padStart(2,'0')} ${w.unitType==='sentence'?'· 整句学习':w.contextCue&&!usageData[w.id]?.meaning?'· 原文语境提示':''}</small><h3 lang="en">${esc(w.word)}</h3><p>${esc(meaning(w))}</p>${audio(w.word,w.unitType==='sentence'?'播放整句发音':'播放发音')}${usagePanel(w,true)}${w.unitType==='sentence'?`<p class="small">完整意思一起记；回忆时也填写整句。</p>`:''}${w.note?`<details><summary>用法与原文核对</summary><p>${esc(w.note)}</p>${w.sourceContext?`<p>完整原文语境：${esc(w.sourceContext)}</p>`:''}${w.components?`<p>本句原搭配：${w.components.map(c=>esc(c.word)).join(' · ')}</p>`:''}${w.sources?.[0]?.phrase?`<p>原表达：${esc(w.sources[0].phrase)}<br>原语境：${esc(w.sources[0].cue)}</p>`:''}${source(w)}</details>`:source(w)}</article>`}).join('')}</div>`;}
function blockStudy(s){const g=training.groups.find(g=>g.id===s.groupId);return `<div class="eyebrow">NOTICE CONNECTIONS / 成组预习</div><h1>${g?esc(g.title):'先把这组表达放在一起看。'}</h1><p>本次 ${s.ids.length} 项。先学习中文意思、英文结构和搭配用法；准备好后隐藏英文，根据中文表达。发音按需点击。</p>${s.kind==='collocation'&&g?groupArgument(g):''}${promptSettings()}${s.kind==='collocation'?'<p class="small">标为“整句学习”的条目需写出完整英文句子，原搭配仅供对照。独立短语仍保留原文语境提示；请关注句子结构及使用条件。</p>':''}${studyCards(s.ids)}<div class="actions"><button class="primary" data-action="next">准备好了，隐藏英文开始回忆 <kbd>Enter ↵</kbd></button></div>`;}
function translationQuestion(s){const w=current();return `<div class="eyebrow">THINK IN MEANING / WRITE IN ENGLISH</div><h1>${w.unitType==='sentence'?'把这个意思，写成完整句子。':'这个意思，用英文怎么表达？'}</h1><p class="input-label">${w.contextCue&&!usageData[w.id]?.meaning?'中文语境提示':'中文意思'}</p><p class="meaning-prompt">${esc(meaning(w))}</p><p class="small">${w.contextCue&&!usageData[w.id]?.meaning?'根据语境写出本次学过的目标表达，背景信息不必全部照译。':'用刚刚学过的词语、搭配或完整句子表达。'}${s.kind==='vocab'?'练习教材目标词的拼写；答对自动朗读，答错进入订正。':'本题允许合理改写，请核对语法、搭配与核心要点。'}</p>${audio(w.word,w.unitType==='sentence'?'播放整句发音（可选）':'播放发音（可选）')}<details class="usage-hint"><summary>查看用法与搭配提示（会显示英文）</summary>${usagePanel(w)}</details>${answerForm('根据中文写出英文表达','把中文意思表达成英文…')}`;}

function blockComplete(s){const g=training.groups.find(g=>g.id===s.groupId),done=g?groupProgress(g,state):0;return `<div class="complete-symbol">✦</div><h1>这一小组，练完了。</h1><p>本次完成 ${s.ids.length} 项回忆与纠错。${g?`本板块累计已练 ${done} / ${g.entryIds.length} 项。`:''}</p>${g?`<div class="optional-essay"><span class="eyebrow">OPTIONAL / 由你选择下一步</span><h2>把表达放进完整文章。</h2><p>关联范文选用本话题的部分表达。先按中文提示补全关键短语和句子，提交后查看答案及论证顺序。</p><div class="actions"><button class="primary" data-open-essay="${g.essayId}" data-return-group="${g.id}">进入范文填空 →</button><button class="secondary" data-action="end">跳过范文，结束学习</button></div>${done<g.entryIds.length?`<button class="quiet" data-start-group="${g.id}">先继续本板块剩余 ${g.entryIds.length-done} 项 →</button>`:''}</div>`:`<div class="actions"><a class="primary" href="#essays">选择话题范文</a><button class="secondary" data-action="end">结束学习</button></div>`}<a class="text-link" href="#${s.kind==='vocab'?'vocabulary':'collocations'}">返回板块目录 →</a>`;}
function essayIndex(){const pending=training.essays.filter(e=>{const d=courseState.essays[e.id];return d&&e.gaps.some(g=>d.everWrong[g.id]&&!gapMatches(d.answers[g.id],g));});$('#main').innerHTML=header('FROM WORDS TO AN ESSAY','把词汇，连成一条论证。','27 篇原创 Task 2 教学范文，关联全部 28 个词汇板块与 20 个搭配话题。先给中文提示，提交后看答案和思路。')+`<p class="small">每篇 ${Math.min(...training.essays.map(e=>e.wordCount))}–${Math.max(...training.essays.map(e=>e.wordCount))} 词。示范合理使用部分相关表达，不是官方范文或评分保证。<a class="text-link" href="https://ielts.org/take-a-test/test-types/ielts-academic-test/ielts-academic-format-writing" target="_blank" rel="noopener">IELTS 官方写作要求 ↗</a></p><div class="method-banner"><span>01 审题</span><i>→</i><span>02 中文提示填空</span><i>→</i><span>03 对照答案</span><i>→</i><span>04 理清思路</span></div>${pending.length?`<div class="resume"><b>${pending.length} 篇范文还有未匹配的历史错空</b><a href="#essay/${pending[0].id}" class="primary">继续巩固 →</a></div>`:''}<div class="course-groups">${training.essays.map(e=>{const d=courseState.essays[e.id];return `<a class="course-group panel" href="#essay/${e.id}"><span class="eyebrow">${e.wordCount} WORDS · ${e.gaps.length} GAPS</span><h3>${esc(e.title)}</h3><p>${esc(e.sections.join(' / ')||e.topics.map(id=>data.topics.find(t=>t.id===id).title).join(' / '))}</p><span class="text-link">${d?.completed?'✓ 曾全部匹配 · 再练一次':d?.attempts?'继续巩固 →':'开始填空 →'}</span></a>`}).join('')}</div>`;}
function essayPage(id){correctionRequests.clear();const e=training.essays.find(e=>e.id===id);if(!e){location.hash='essays';return;}const d=essayDraft(courseState,e),checked=d.submitted,correct=e.gaps.filter(g=>gapMatches(d.answers[g.id],g)).length;$('#main').innerHTML=header('OPTIONAL WRITING PRACTICE',esc(e.title),`${e.wordCount} 词 · ${e.gaps.length} 个空 · ${e.taskType}`)+`<div class="actions"><a href="#essays" class="text-link">← 全部范文</a>${training.groups.some(g=>g.id===courseState.returnGroup&&g.essayId===e.id)?`<a class="text-link" href="#group/${courseState.returnGroup}">返回刚才的板块</a>`:''}<button class="secondary" data-skip-essay="${e.id}">跳过 / 结束本篇</button><button class="quiet" data-action="export">导出学习记录 ↓</button></div><section class="panel essay-prompt"><h2>先审题</h2><p lang="en">${esc(e.prompt)}</p><p class="small">填入本篇目标表达。系统按参考答案与列明的可接受形式核对，未匹配不代表你的其他写法一定错误，也不是雅思评分。所有空填写后提交，才显示参考答案与文章思路。</p></section>${checked?`<section class="panel essay-feedback" id="essay-feedback" role="status"><h2>${correct===e.gaps.length?'✓ 本篇目标表达全部匹配':'还有表达值得再推敲'}</h2><p>本次匹配 ${correct} / ${e.gaps.length} 个空。对照下面的答案与论证顺序；其他合理表述可结合上下文自行核对。</p><div class="actions">${correct<e.gaps.length?`<button class="primary" data-retry-essay="${e.id}" data-wrong-only="true">只重练未匹配的空 →</button>`:''}<button class="secondary" data-retry-essay="${e.id}">隐藏答案，重新练整篇</button></div></section>`:''}<form id="essay-form" data-essay="${e.id}"><div class="essay-paper">${e.paragraphs.map((para,i)=>`<section class="essay-paragraph"><h2><span>${String(i+1).padStart(2,'0')}</span> ${para.role}</h2><div lang="en" class="essay-prose">${paragraphParts(e,i).map(part=>{if(!part.gap)return esc(part.text);const g=part.gap,n=e.gaps.indexOf(g)+1;if(checked)return `<mark>${esc(g.answer)}</mark>`;return `<span class="essay-blank"><label lang="zh-CN" for="${e.id}-${g.id}">空 ${n} · ${esc(g.hint)}</label>${g.answer.length>60?`<textarea rows="3"`:`<input type="text"`} id="${e.id}-${g.id}" data-essay-gap="${g.id}" data-essay-id="${e.id}" maxlength="2000" spellcheck="false" autocomplete="off" autocapitalize="none" ${g.answer.length>60?'':`value="${esc(d.answers[g.id]||'')}"`}>${g.answer.length>60?esc(d.answers[g.id]||'')+'</textarea>':''}</span>`;}).join('')}</div></section>`).join('')}</div>${!checked?`<p id="essay-error" class="error" role="status"></p><div class="actions"><button type="submit" class="primary">提交整篇，查看答案与思路 →</button><span class="small">输入自动保存在此浏览器。</span></div>`:''}</form>${checked?`<section class="essay-key"><div class="section-title"><h2>逐空核对 · 语句怎样发挥作用</h2></div>${e.gaps.map((g,i)=>`<article class="panel"><span class="${gapMatches(d.answers[g.id],g)?'feedback':'small'}">${gapMatches(d.answers[g.id],g)?'✓ 已匹配':'其他表述 · 待核对'} · 空 ${i+1}</span><p class="small">你的答案：<span lang="en">${esc(d.answers[g.id])}</span></p><h3 lang="en">${esc(g.answer)}</h3><p>${esc(g.hint)}</p>${audio(g.answer,'听参考表达')}<p class="small">${esc(g.explanation)}</p>${!gapMatches(d.answers[g.id],g)?correctionPanel({id:e.id+'-'+g.id,word:g.answer,meaning:g.hint,acceptedAnswers:g.acceptedAnswers,unitType:'sentence'},d.answers[g.id],e.paragraphs[g.paragraph].text):''}</article>`).join('')}</section><section class="panel essay-plan"><div class="eyebrow">FOLLOW THE REASONING</div><h2>这篇文章的思路是怎样顺下来的？</h2><div class="callout"><strong>立场</strong><p>${esc(e.stance)}</p></div><ol class="steps">${e.plan.map(p=>`<li><b>${p.role}</b><span>${esc(p.idea)}</span></li>`).join('')}</ol><h3>迁移到自己的文章</h3><p>${esc(e.transfer)}</p><p class="small">范文是本站原创教学示例，题目为自拟；不用虚构统计数字，也不以记住范文代替回应新题。</p></section>`:''}`;}
function submitEssayPage(){const e=training.essays.find(x=>x.id===$('#essay-form').dataset.essay),result=checkEssay(courseState,e);if(result.missing){$('#essay-error').textContent=`还有 ${result.missing.length} 个空未填写。可以继续填写，或选择“跳过 / 结束本篇”。`;document.getElementById(`${e.id}-${result.missing[0]}`).focus();return;}saveCourse();essayPage(e.id);$('#essay-feedback').scrollIntoView({block:'start'});}
function handleCourseClick(b){if(b.dataset.startGroup){const g=training.groups.find(g=>g.id===b.dataset.startGroup);if(!g)return true;let ids=nextGroupIds(g,state,state.settings.size);if(state.settings.shuffle){ids=[...ids];for(let i=ids.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[ids[i],ids[j]]=[ids[j],ids[i]];}}begin(g.kind,ids,g.id);return true;}if(b.dataset.openEssay){courseState.returnGroup=b.dataset.returnGroup||'';saveCourse();location.hash='essay/'+b.dataset.openEssay;return true;}if(b.dataset.retryEssay){const e=training.essays.find(e=>e.id===b.dataset.retryEssay);retryEssay(courseState,e,b.dataset.wrongOnly==='true');saveCourse();essayPage(e.id);$('#essay-form input, #essay-form textarea')?.focus();return true;}if(b.dataset.skipEssay){saveCourse();const g=training.groups.find(g=>g.id===courseState.returnGroup&&g.essayId===b.dataset.skipEssay);location.hash=g?'group/'+g.id:'essays';toast('已结束本篇，已填写的内容保留；不会标记为完成。');return true;}return false;}
function essayReview(){const es=training.essays.filter(e=>Object.values(courseState.essays[e.id]?.everWrong||{}).some(Boolean));return `<section class="panel essay-review"><h2>范文表达核对记录</h2><p class="small">这里保留与参考不同的填空，不代表语言错误；请结合上下文与 AI 讲评核对。</p>${es.map(e=>{const d=courseState.essays[e.id],pending=e.gaps.filter(g=>d.everWrong[g.id]&&!gapMatches(d.answers[g.id],g)).length;return `<p><a class="text-link" href="#essay/${e.id}">${esc(e.title)} →</a> · ${pending?pending+' 个历史填空待核对':'历史填空已匹配参考'}</p>`}).join('')||'<p>还没有范文表达核对记录。</p>'}<a href="#essays" class="secondary">选择一篇范文</a></section>`;}

function usagePanel(w,compact=false){const u=usageData?.[w.id];if(!u)return '';const names={noun:'名词性表达',verb:'动词表达',adjective:'形容词表达',adverb:'补充说明',sentence:'完整句子的用法'};const body=`<div class="usage-content"><p class="usage-kind">${names[u.kind]||'表达用法'}</p><p class="usage-pattern" lang="en">${esc(u.pattern)}</p><h4>搭配结构</h4><ul>${u.collocations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h4>怎么用</h4><ul>${u.notes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${w.note&&!w.contextCue&&!w.componentIds?`<p class="tip">${esc(w.note)}</p>`:''}${u.example&&w.unitType!=='sentence'?`<div class="usage-example"><h4>放进句子里</h4><p lang="en">${esc(u.example.text)}</p>${u.example.translation?`<p class="small">${esc(u.example.translation)}</p>`:''}${audio(u.example.text,'播放例句')}<small>${esc(u.example.source)}</small></div>`:''}${w.components?.length?`<div class="sentence-components"><h4>句中的搭配怎样使用</h4><p class="small">只拆解用法帮助理解，练习仍写完整句子。</p>${w.components.map(c=>{const part=usageData[c.id];return part?`<details><summary lang="en">${esc(c.word)}</summary><p class="usage-pattern">${esc(part.pattern)}</p><ul>${part.collocations.map(x=>`<li>${esc(x)}</li>`).join('')}${part.notes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''}).join('')}</div>`:''}</div>`;return compact?`<details class="usage-guide"><summary>怎么用 · 搭配与例句</summary>${body}</details>`:`<section class="usage-guide"><h3>怎么用 · 搭配与用法</h3>${body}</section>`;}

function correctionPanel(w,answer,context=''){
 const result=compareExpression(answer,w),u=usageData?.[w.id],requestKey=w.id+'|'+answer;
 correctionRequests.set(requestKey,{answer,entry:{...w,meaning:meaning(w),contextCue:w.contextCue&&!u?.meaning},usage:u,context});
 return `<section class="correction-panel"><div class="eyebrow">GRAMMAR & COLLOCATION</div><h3>核对语法、搭配与表达原意</h3><div class="comparison-grid"><div><h4>你的完整表达</h4><p lang="en">${esc(answer)||'（未填写）'}</p></div><div><h4>一种参考表达</h4><p lang="en">${esc(result.reference)}</p></div></div><p class="small">${result.matched?'已匹配本题收录的表达。':w.id.startsWith('v-')?'本次未匹配教材目标词的拼写，请对照目标词与已收录的拼写变体订正。':'尚未判断对错。合理的同义替换、语序变化和句式改写都可以成立。'}</p>${corePhrases(w).length?`<div class="correction-focus"><h4>本题要保留的重点表达</h4><ul>${corePhrases(w).map(p=>`<li lang="en">${esc(p)}</li>`).join('')}</ul><p class="small">可以按句意调整词形、时态、语态和修饰语；重点表达须保留，不能漏用或用错。</p></div>`:''}<h4>核对重点</h4><ul><li>原意：对象、动作、逻辑关系及限定条件是否准确？</li><li>语法：主谓一致、时态、冠词、词形和从句结构是否成立，整句是否通顺？</li><li>搭配与短语：动词与宾语、介词及后接结构是否自然？</li></ul><p class="small">以下是用法参考；具体错误由 AI 结合语境分析，或由你核对确认。风格润色与必要订正分开处理。</p>${u?`<div class="correction-focus"><h4>结合本条搭配检查</h4><p>${esc(u.pattern)}</p><ul>${u.notes.slice(0,3).map(n=>`<li>${esc(n)}</li>`).join('')}</ul></div>`:''}${teacherControls(requestKey)}<details class="teacher-handoff"><summary>也可以复制给其他 AI 请教</summary><p class="small">可复制本题、你的表达和用法，交给你使用的 AI，进一步判断语法、解释原因、给出订正版。复制操作不会自动调用 AI。</p><button type="button" class="secondary" data-copy-teacher="${esc(requestKey)}">复制题目与讲评要求</button><details class="teacher-copy"><summary>查看 / 手动复制请教内容</summary><textarea readonly aria-label="给 AI 老师的讲评资料">${esc(teacherPrompt(correctionRequests.get(requestKey)))}</textarea></details><p class="copy-status small" role="status"></p></details></section>`;
}
function handleCorrectionClick(button){
 if(button.dataset.aiReview){const payload=correctionRequests.get(button.dataset.aiReview),session=state.session;if(payload)requestReview(button,payload).then(result=>{
 if(!result||state.session!==session||location.hash!=='#practice'||!button.isConnected)return;
 const accepted=acceptTeacherReview(state,payload.entry,payload.answer,result.review);
 if(accepted==='ignored')return;save();practice();
 const info=document.createElement('p');info.className='small';info.textContent=(result.cached?'复用讲评；原用量：':'本次讲评用量：')+`输入 ${result.usage.input??'未提供'} / 输出 ${result.usage.output??'未提供'} tokens。`;
 document.querySelector('.exercise')?.append(info);
 if(accepted==='repair-progress')toast('AI 核对通过，已计入本次巩固次数。');
 });return true;}
 if(!button.dataset.copyTeacher)return false;
 const panel=button.closest('.teacher-handoff'),payload=correctionRequests.get(button.dataset.copyTeacher);if(!payload)return true;
 const fallback=()=>{panel.querySelector('details').open=true;const box=panel.querySelector('textarea');box.focus();box.select();panel.querySelector('.copy-status').textContent='请复制已选中的内容，再粘贴到你使用的 AI 对话中。';};
 if(!navigator.clipboard?.writeText){fallback();return true;}
 navigator.clipboard.writeText(teacherPrompt(payload)).then(()=>{panel.querySelector('.copy-status').textContent='已复制。粘贴到你使用的 AI 对话中，即可请老师逐项讲解。';}).catch(fallback);return true;
}

function phraseList(ids){const seen=new Set();return ids.flatMap(id=>{const w=byId.get(id);return w.components?.length?w.components.map(c=>({word:c.word,meaning:c.meaning||''})):w.unitType==='sentence'?[]:[{word:w.word,meaning:meaning(w)}];}).filter(p=>{const key=p.word.toLowerCase();if(seen.has(key))return false;seen.add(key);return true;});}
function topicRoadmap(t,groups){const angles=new Map();for(const g of groups){const title=g.title.replace(/ · \d+\/\d+$/,'');if(!angles.has(title))angles.set(title,[]);angles.get(title).push(g);}const essay=training.essays.find(e=>e.id===groups[0]?.essayId);return `<section class="panel topic-roadmap"><div class="eyebrow">TOPIC → IDEAS → EXPRESSIONS</div><h2>这个话题，可以从哪些方面写？</h2><p>以下按教材内容归纳为 ${angles.size} 个角度，覆盖本话题全部学习项。审题后选最相关的两到三个角度，不必把所有素材塞进同一篇文章。</p><div class="course-groups">${[...angles].map(([title,gs],i)=>{const ids=gs.flatMap(g=>g.entryIds),phrases=phraseList(ids);return `<article class="panel"><span class="eyebrow">ANGLE ${i+1}</span><h3>${esc(title)}</h3><p>${ids.length} 项表达 · ${phrases.length} 个重点词组</p><details><summary>查看这个角度的全部重点词组</summary><ul>${phrases.map(p=>`<li><strong lang="en">${esc(p.word)}</strong>${p.meaning?' · '+esc(p.meaning):''}</li>`).join('')}</ul></details><div class="actions">${gs.map((g,j)=>`<a class="text-link" href="#group/${g.id}">学习${gs.length>1?'第 '+(j+1)+' 组':'本角度'} →</a>`).join('')}</div></article>`;}).join('')}</div>${essay?`<details class="topic-outline"><summary>示范：怎样把角度串成一篇文章</summary><p lang="en">${esc(essay.prompt)}</p><p><b>立场：</b>${esc(essay.stance)}</p><ol>${essay.plan.map(p=>`<li><b>${esc(p.role)}</b>：${esc(p.idea)}</li>`).join('')}</ol><a class="text-link" href="#essay/${essay.id}">按中文提示完成范文 →</a></details>`:''}</section>`;}
function groupArgument(g){const ids=g.entryIds,phrases=phraseList(ids),sample=ids.map(id=>byId.get(id)).find(w=>w.unitType==='sentence');return `<section class="panel argument-guide"><div class="eyebrow">BUILD A PARAGRAPH</div><h2>从「${esc(g.title.replace(/ · \d+\/\d+$/,''))}」展开</h2><ol class="steps"><li><b>观点</b><span>明确谁受到影响，以及这一角度怎样回答题目。</span></li><li><b>原因</b><span>解释“为什么、通过什么过程”，不要只罗列好处或坏处。</span></li><li><b>例子与边界</b><span>给一个具体情境，说明适用条件；避免把可能性写成必然结果。</span></li><li><b>回扣题目</b><span>说明这个影响为什么支持你的立场。</span></li></ol><details><summary>本组全部 ${phrases.length} 个重点词组 · 先连在一起记</summary><ul>${phrases.map(p=>`<li lang="en">${esc(p.word)}</li>`).join('')}</ul></details>${sample?`<div class="callout"><h3>本组整句示范</h3><p>${esc(meaning(sample))}</p><p lang="en">${esc(sample.word)}</p>${audio(sample.word,'播放整句')}<p class="small">先理解这一句表达的关系，再用下方各项用法检查介词、词形和句子结构。整句保持完整，不拆成多道短语题。</p></div>`:''}<p class="small">表达核对：语法、通顺度、核心意思、重点短语。与参考不同的句子先标为待核对，可请 AI 老师检查；AI 也可能误判，有疑问可保留待核对。</p></section>`;}
